insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social stratification', 'Social stratification refers to a society''s hierarchical categorization of its people into groups based on socioeconomic factors such as wealth, income, race, education, ethnicity, gender, occupation, social status, or derived power (social and political). It is a hierarchy within groups that ascribe them to different levels of privileges. As such, stratification is the relative social position of persons within a social group, category, geographic region, or social unit. The concept of social stratification (as well as the concept of social mobility) was introduced by a Russian-American sociologist Pitirim Sorokin in his book "Social Mobility" published in 1927. In modern Western societies, social stratification is defined in terms of three social classes: an upper class, a middle class, and a working class; in turn, each class can be subdivided into an upper-stratum, a middle-stratum, and a lower stratum. Moreover, a social stratum can be formed upon the bases of kinship, clan, tribe, or caste, or all four.', 'Wikipedia: Social stratification', 'https://en.wikipedia.org/w/index.php?title=Social_stratification&oldid=1376077231', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Social stratification refers to a society''s hierarchical categorization of its people into groups based on socioeconomic factors such as wealth, income, race, education, ethnicity, gender, occupation, social status, or derived power (social and political). It is a hierarchy within groups that ascribe them to different levels of privileges. As such, stratification is the relative social position of persons within a social group, category, geographic region, or social unit. The concept of social stratification (as well as the concept of social mobility) was introduced by a Russian-American sociologist Pitirim Sorokin in his book "Social Mobility" published in 1927. In modern Western societies, social stratification is defined in terms of three social classes: an upper class, a middle class, and a working class; in turn, each class can be subdivided into an upper-stratum, a middle-stratum, and a lower stratum. Moreover, a social stratum can be formed upon the bases of kinship, clan, tribe, or caste, or all four.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social stratification', 'The categorization of people by social stratum occurs most clearly in complex state-based, polycentric, or feudal societies, the latter being based upon socio-economic relations among classes of nobility and classes of peasants. Whether social stratification first appeared in hunter-gatherer, tribal, and band societies or whether it began with agriculture and large-scale means of social exchange remains a matter of debate in the social sciences. The structures of social stratification arise from inequalities of status among persons; therefore, the degree of social inequality determines a person''s social stratum. Generally, the greater the social complexity of a society, the more social stratification exists, by way of social differentiation.', 'Wikipedia: Social stratification', 'https://en.wikipedia.org/w/index.php?title=Social_stratification&oldid=1376077231', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'The categorization of people by social stratum occurs most clearly in complex state-based, polycentric, or feudal societies, the latter being based upon socio-economic relations among classes of nobility and classes of peasants. Whether social stratification first appeared in hunter-gatherer, tribal, and band societies or whether it began with agriculture and large-scale means of social exchange remains a matter of debate in the social sciences. The structures of social stratification arise from inequalities of status among persons; therefore, the degree of social inequality determines a person''s social stratum. Generally, the greater the social complexity of a society, the more social stratification exists, by way of social differentiation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social stratification: Definition and usage', '"Social stratification" is a concept used in the social sciences to describe the relative social position of persons in a given social group, category, geographical region or other social unit. It derives from the Latin strātum (plural ''strata''; parallel, horizontal layers) referring to a given society''s categorization of its people into rankings of socioeconomic tiers based on factors like wealth, income, social status, occupation and power. In modern Western societies, stratification is often broadly classified into three major divisions of social class: upper class, middle class, and working class. Each of these classes can be further subdivided into smaller classes (e.g. "upper middle"). Social strata may also be delineated on the basis of kinship ties or caste relations.', 'Wikipedia: Social stratification', 'https://en.wikipedia.org/w/index.php?title=Social_stratification&oldid=1376077231', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = '"Social stratification" is a concept used in the social sciences to describe the relative social position of persons in a given social group, category, geographical region or other social unit. It derives from the Latin strātum (plural ''strata''; parallel, horizontal layers) referring to a given society''s categorization of its people into rankings of socioeconomic tiers based on factors like wealth, income, social status, occupation and power. In modern Western societies, stratification is often broadly classified into three major divisions of social class: upper class, middle class, and working class. Each of these classes can be further subdivided into smaller classes (e.g. "upper middle"). Social strata may also be delineated on the basis of kinship ties or caste relations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social stratification: Definition and usage', 'The concept of social stratification is often used and interpreted differently within specific theories. In sociology, for example, proponents of action theory have suggested that social stratification is commonly found in developed societies, wherein a dominance hierarchy may be necessary in order to maintain social order and provide a stable social structure. Conflict theories, such as Marxism, point to the inaccessibility of resources and lack of social mobility found in stratified societies. Many sociological theorists have criticized the fact that the working classes are often unlikely to advance socioeconomically while the wealthy tend to hold political power which they use to exploit the proletariat (laboring class). Talcott Parsons, an American sociologist, asserted that stability and social order are regulated, in part, by universal values. Such values are not identical with "consensus" but can indeed be an impetus for social conflict, as has been the case multiple times through history. Parsons never claimed that universal values, in and by themselves, "satisfied" the functional prerequisites of a society. Indeed, the constitution of society represents a much more complicated codification of emerging historical factors. Theorists such as Ralf Dahrendorf alternately note the tendency toward an enlarged middle-class in modern Western societies due to the necessity of an educated workforce in technological economies. Various social and political perspectives concerning globalization, such as dependency theory, suggest that these effects are due to changes in the status of workers to the third world.', 'Wikipedia: Social stratification', 'https://en.wikipedia.org/w/index.php?title=Social_stratification&oldid=1376077231', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'The concept of social stratification is often used and interpreted differently within specific theories. In sociology, for example, proponents of action theory have suggested that social stratification is commonly found in developed societies, wherein a dominance hierarchy may be necessary in order to maintain social order and provide a stable social structure. Conflict theories, such as Marxism, point to the inaccessibility of resources and lack of social mobility found in stratified societies. Many sociological theorists have criticized the fact that the working classes are often unlikely to advance socioeconomically while the wealthy tend to hold political power which they use to exploit the proletariat (laboring class). Talcott Parsons, an American sociologist, asserted that stability and social order are regulated, in part, by universal values. Such values are not identical with "consensus" but can indeed be an impetus for social conflict, as has been the case multiple times through history. Parsons never claimed that universal values, in and by themselves, "satisfied" the functional prerequisites of a society. Indeed, the constitution of society represents a much more complicated codification of emerging historical factors. Theorists such as Ralf Dahrendorf alternately note the tendency toward an enlarged middle-class in modern Western societies due to the necessity of an educated workforce in technological economies. Various social and political perspectives concerning globalization, such as dependency theory, suggest that these effects are due to changes in the status of workers to the third world.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social stratification: Four underlying principles', 'Four principles are posited to underlie social stratification. First, social stratification is socially defined as a property of a society rather than individuals in that society. Second, social stratification is reproduced from generation to generation. Third, social stratification is universal (found in every society) but variable (differs across time and place). Fourth, social stratification involves not just quantitative inequality but qualitative beliefs and attitudes about social status.', 'Wikipedia: Social stratification', 'https://en.wikipedia.org/w/index.php?title=Social_stratification&oldid=1376077231', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Four principles are posited to underlie social stratification. First, social stratification is socially defined as a property of a society rather than individuals in that society. Second, social stratification is reproduced from generation to generation. Third, social stratification is universal (found in every society) but variable (differs across time and place). Fourth, social stratification involves not just quantitative inequality but qualitative beliefs and attitudes about social status.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social stratification: Complexity', 'Although stratification is not limited to complex societies, all complex societies exhibit features of stratification. In any complex society, the total stock of valued goods is distributed unequally, wherein the most privileged individuals and families enjoy a disproportionate share of income, power, and other valued social resources. The term "stratification system" is sometimes used to refer to the complex social relationships and social structures that generate these observed inequalities. The key components of such systems are: (a) social-institutional processes that define certain types of goods as valuable and desirable, (b) the rules of allocation that distribute goods and resources across various positions in the division of labor (e.g., physician, farmer, ''housewife''), and (c) the social mobility processes that link individuals to positions and thereby generate unequal control over valued resources.', 'Wikipedia: Social stratification', 'https://en.wikipedia.org/w/index.php?title=Social_stratification&oldid=1376077231', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Although stratification is not limited to complex societies, all complex societies exhibit features of stratification. In any complex society, the total stock of valued goods is distributed unequally, wherein the most privileged individuals and families enjoy a disproportionate share of income, power, and other valued social resources. The term "stratification system" is sometimes used to refer to the complex social relationships and social structures that generate these observed inequalities. The key components of such systems are: (a) social-institutional processes that define certain types of goods as valuable and desirable, (b) the rules of allocation that distribute goods and resources across various positions in the division of labor (e.g., physician, farmer, ''housewife''), and (c) the social mobility processes that link individuals to positions and thereby generate unequal control over valued resources.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social stratification: Social mobility', 'Social mobility is the movement of individuals, social groups or categories of people between the layers or within a stratification system. This movement can be intragenerational or intergenerational. Such mobility is sometimes used to classify different systems of social stratification. Open stratification systems are those that allow for mobility between, typically by placing value on the achieved status characteristics of individuals. Those societies having the highest levels of intragenerational mobility are considered to be the most open and malleable systems of stratification. Those systems in which there is little to no mobility, even on an intergenerational basis, are considered closed stratification systems. For example, in caste systems, all aspects of social status are ascribed, such that one''s social position at birth persists throughout one''s lifetime.', 'Wikipedia: Social stratification', 'https://en.wikipedia.org/w/index.php?title=Social_stratification&oldid=1376077231', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Social mobility is the movement of individuals, social groups or categories of people between the layers or within a stratification system. This movement can be intragenerational or intergenerational. Such mobility is sometimes used to classify different systems of social stratification. Open stratification systems are those that allow for mobility between, typically by placing value on the achieved status characteristics of individuals. Those societies having the highest levels of intragenerational mobility are considered to be the most open and malleable systems of stratification. Those systems in which there is little to no mobility, even on an intergenerational basis, are considered closed stratification systems. For example, in caste systems, all aspects of social status are ascribed, such that one''s social position at birth persists throughout one''s lifetime.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social stratification: Karl Marx', 'In Marxist theory, the modern mode of production consists of two main economic parts: the base and the superstructure. The base encompasses the relations of production: employer–employee work conditions, the technical division of labour, and property relations. Social class, according to Marx, is determined by one''s relationship to the means of production. There exist at least two classes in any class-based society: the owners of the means of production and those who have to sell their labor to the owners of the means of production. At times, Marx almost hints that the ruling classes seem to own the working class itself as they only have their own labor power (''wage labor'') to offer the more powerful in order to survive. These relations fundamentally determine the ideas and philosophies of a society and additional classes may form as part of the superstructure. Through the ideology of the ruling class—throughout much of history, the land-owning aristocracy—false consciousness is promoted both through political and non-political institutions but also through the arts and other elements of culture. When the aristocracy falls, the bourgeoisie become the owners of the means of production in the capitalist system. Marx predicted the capitalist mode would eventually give way, through its own internal conflict, to revolutionary consciousness and the development of more egalitarian, more communist societies.', 'Wikipedia: Social stratification', 'https://en.wikipedia.org/w/index.php?title=Social_stratification&oldid=1376077231', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'In Marxist theory, the modern mode of production consists of two main economic parts: the base and the superstructure. The base encompasses the relations of production: employer–employee work conditions, the technical division of labour, and property relations. Social class, according to Marx, is determined by one''s relationship to the means of production. There exist at least two classes in any class-based society: the owners of the means of production and those who have to sell their labor to the owners of the means of production. At times, Marx almost hints that the ruling classes seem to own the working class itself as they only have their own labor power (''wage labor'') to offer the more powerful in order to survive. These relations fundamentally determine the ideas and philosophies of a society and additional classes may form as part of the superstructure. Through the ideology of the ruling class—throughout much of history, the land-owning aristocracy—false consciousness is promoted both through political and non-political institutions but also through the arts and other elements of culture. When the aristocracy falls, the bourgeoisie become the owners of the means of production in the capitalist system. Marx predicted the capitalist mode would eventually give way, through its own internal conflict, to revolutionary consciousness and the development of more egalitarian, more communist societies.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social mobility', 'Social mobility is the movement of people within or between social strata in a society. It is a change in social status relative to one''s initial status in a given society. This movement occurs between layers or tiers in an open system of social stratification. Open stratification systems are those in which at least some value is given to achieved status characteristics in a society. Movement can be in a downward or upward direction. Markers for social mobility such as education and class, are used to predict, discuss, and learn more about movement in society.', 'Wikipedia: Social mobility', 'https://en.wikipedia.org/w/index.php?title=Social_mobility&oldid=1380459640', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Social mobility is the movement of people within or between social strata in a society. It is a change in social status relative to one''s initial status in a given society. This movement occurs between layers or tiers in an open system of social stratification. Open stratification systems are those in which at least some value is given to achieved status characteristics in a society. Movement can be in a downward or upward direction. Markers for social mobility such as education and class, are used to predict, discuss, and learn more about movement in society.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social mobility: Typology', 'Mobility is most often measured in terms of change in economic mobility such as changes in income or wealth. Occupation is another measure used in mobility research. Mobility may be intragenerational, within the same generation or intergenerational, between different generations. The idea of intergenerational mobility is one of the fundamental features of the "American Dream" even though there is less such mobility in the United States of America than almost all other OECD countries.', 'Wikipedia: Social mobility', 'https://en.wikipedia.org/w/index.php?title=Social_mobility&oldid=1380459640', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Mobility is most often measured in terms of change in economic mobility such as changes in income or wealth. Occupation is another measure used in mobility research. Mobility may be intragenerational, within the same generation or intergenerational, between different generations. The idea of intergenerational mobility is one of the fundamental features of the "American Dream" even though there is less such mobility in the United States of America than almost all other OECD countries.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social mobility: Social status and social class', 'Social mobility depends heavily on the overall structure of social statuses and occupations in a given society. Education offers an opportunity for upward social mobility and higher social status. However, social stratification and high wealth inequality directly affect educational opportunities and outcomes. Social class and a family''s socioeconomic status directly affect a child''s chances for obtaining a quality education and succeeding in life. By age five, low-, middle-, and upper-class children show significant differences in cognitive and noncognitive skills. According to a 2013 Brookings Institution report on social mobility: Among older children, evidence suggests that the gap between high- and low-income primary- and secondary-school students has increased by almost 40 percent over the past thirty years. These differences persist and widen into young adulthood and beyond. As the gap in K–12 test scores between high- and low-income students grows, so does the gap in college graduation rates between the rich and the poor. Although the college graduation rate among the poorest households increased by about 4 percentage points between those born in the early 1960s and those born in the early 1980s, it rose by almost 20 percentage points for the wealthiest households over the same period.', 'Wikipedia: Social mobility', 'https://en.wikipedia.org/w/index.php?title=Social_mobility&oldid=1380459640', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Social mobility depends heavily on the overall structure of social statuses and occupations in a given society. Education offers an opportunity for upward social mobility and higher social status. However, social stratification and high wealth inequality directly affect educational opportunities and outcomes. Social class and a family''s socioeconomic status directly affect a child''s chances for obtaining a quality education and succeeding in life. By age five, low-, middle-, and upper-class children show significant differences in cognitive and noncognitive skills. According to a 2013 Brookings Institution report on social mobility: Among older children, evidence suggests that the gap between high- and low-income primary- and secondary-school students has increased by almost 40 percent over the past thirty years. These differences persist and widen into young adulthood and beyond. As the gap in K–12 test scores between high- and low-income students grows, so does the gap in college graduation rates between the rich and the poor. Although the college graduation rate among the poorest households increased by about 4 percentage points between those born in the early 1960s and those born in the early 1980s, it rose by almost 20 percentage points for the wealthiest households over the same period.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social mobility: Social status and social class', 'Between 1975 and 2011, average family income and social status have both decreased for the bottom third of children. The 5th percentile of children and their families have seen up to a 60% decrease in average family income. The wealth gap between the rich and the poor, the upper and lower class, continues to increase as more middle-class people get poorer and the lower-class get even poorer. A child born to parents in the lowest-income quintile is more than 10 times as likely to end up in the lowest quintile as an adult as a child born to parents in the highest quintile. A child born to parents in the highest quintile is five times more likely to end up in the highest quintile than the lowest. This may be partly because lower- and working-class parents, where neither is educated above high school, spend less time with their children in their earliest years and are less involved in their children''s education and time out of school. This parenting style, known as "accomplishment of natural growth" differs from the style of middle-class and upper-class parents, with at least one parent having higher education, known as "cultural cultivation".', 'Wikipedia: Social mobility', 'https://en.wikipedia.org/w/index.php?title=Social_mobility&oldid=1380459640', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Between 1975 and 2011, average family income and social status have both decreased for the bottom third of children. The 5th percentile of children and their families have seen up to a 60% decrease in average family income. The wealth gap between the rich and the poor, the upper and lower class, continues to increase as more middle-class people get poorer and the lower-class get even poorer. A child born to parents in the lowest-income quintile is more than 10 times as likely to end up in the lowest quintile as an adult as a child born to parents in the highest quintile. A child born to parents in the highest quintile is five times more likely to end up in the highest quintile than the lowest. This may be partly because lower- and working-class parents, where neither is educated above high school, spend less time with their children in their earliest years and are less involved in their children''s education and time out of school. This parenting style, known as "accomplishment of natural growth" differs from the style of middle-class and upper-class parents, with at least one parent having higher education, known as "cultural cultivation".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social mobility: Social status and social class', 'At the bottom of the socioeconomic ladder, parents cannot provide their children with the resources or opportunities they need to improve their lives. As a result, they remain on the same ladder rung as their parents. On the opposite side of the ladder, the high socioeconomic status (SES) parents have the necessary resources and opportunities to ensure that their children also remain on the same rung as them. More affluent social classes are able to spend more time with their children at early ages, and children receive more exposure to interactions and activities that lead to cognitive and non-cognitive development: things like verbal communication, parent-child engagement and being read to daily. These children''s parents are much more involved in their academics and their free time, placing them in extracurricular activities that develop not only additional non-cognitive skills but also academic values, habits, and abilities to better communicate and interact with authority figures. Enrollment in so many activities can often lead to frenetic family lives organized around transporting children to their various activities. Lower-class children often attend lower-quality schools, receive less attention from teachers, and ask for help much less than their higher-class peers.', 'Wikipedia: Social mobility', 'https://en.wikipedia.org/w/index.php?title=Social_mobility&oldid=1380459640', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'At the bottom of the socioeconomic ladder, parents cannot provide their children with the resources or opportunities they need to improve their lives. As a result, they remain on the same ladder rung as their parents. On the opposite side of the ladder, the high socioeconomic status (SES) parents have the necessary resources and opportunities to ensure that their children also remain on the same rung as them. More affluent social classes are able to spend more time with their children at early ages, and children receive more exposure to interactions and activities that lead to cognitive and non-cognitive development: things like verbal communication, parent-child engagement and being read to daily. These children''s parents are much more involved in their academics and their free time, placing them in extracurricular activities that develop not only additional non-cognitive skills but also academic values, habits, and abilities to better communicate and interact with authority figures. Enrollment in so many activities can often lead to frenetic family lives organized around transporting children to their various activities. Lower-class children often attend lower-quality schools, receive less attention from teachers, and ask for help much less than their higher-class peers.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social mobility: Social status and social class', 'A child''s chances for social mobility are primarily determined by the family they are born into. Today, while college applicants from every socioeconomic class are equally qualified, 75% of all entering freshmen at top-tier American institutions come from the uppermost socioeconomic quartile. A family''s class determines the amount of investment and involvement parents have in their children''s educational abilities and success from their earliest years of life, leaving low-income students with less chance for academic success and social mobility due to the effects that the common parenting style of the lower and working-class have on their outlook on and success in education.', 'Wikipedia: Social mobility', 'https://en.wikipedia.org/w/index.php?title=Social_mobility&oldid=1380459640', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'A child''s chances for social mobility are primarily determined by the family they are born into. Today, while college applicants from every socioeconomic class are equally qualified, 75% of all entering freshmen at top-tier American institutions come from the uppermost socioeconomic quartile. A family''s class determines the amount of investment and involvement parents have in their children''s educational abilities and success from their earliest years of life, leaving low-income students with less chance for academic success and social mobility due to the effects that the common parenting style of the lower and working-class have on their outlook on and success in education.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social mobility: Class cultures and social networks', 'These differing dimensions of social mobility can be classified by the types of capital that contribute to changes in mobility. Cultural capital, a term coined by French sociologist Pierre Bourdieu distinguishes between the economic and cultural aspects of class. Bourdieu described three types of capital that place a person in a certain social category: economic capital; social capital; and cultural capital. Economic capital includes economic resources such as cash, credit, and other material assets. Social capital includes resources one achieves based on group membership, networks of influence, relationships, and support from other people. Cultural capital is any advantage a person has that gives them higher status in society, such as education, skills, or other forms of knowledge. Usually, people with all three types of capital have a high status in society. Bourdieu found that the upper social class culture is oriented more toward formal reasoning and abstract thought. The lower social class is geared more towards matters of facts and the necessities of life. He also found that the environment in which a person develops strongly affects the cultural resources a person will have.', 'Wikipedia: Social mobility', 'https://en.wikipedia.org/w/index.php?title=Social_mobility&oldid=1380459640', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'These differing dimensions of social mobility can be classified by the types of capital that contribute to changes in mobility. Cultural capital, a term coined by French sociologist Pierre Bourdieu distinguishes between the economic and cultural aspects of class. Bourdieu described three types of capital that place a person in a certain social category: economic capital; social capital; and cultural capital. Economic capital includes economic resources such as cash, credit, and other material assets. Social capital includes resources one achieves based on group membership, networks of influence, relationships, and support from other people. Cultural capital is any advantage a person has that gives them higher status in society, such as education, skills, or other forms of knowledge. Usually, people with all three types of capital have a high status in society. Bourdieu found that the upper social class culture is oriented more toward formal reasoning and abstract thought. The lower social class is geared more towards matters of facts and the necessities of life. He also found that the environment in which a person develops strongly affects the cultural resources a person will have.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social mobility: Class cultures and social networks', 'The cultural resources a person has obtained can heavily influence a child''s educational success. Students raised under the concerted cultivation approach have "an emerging sense of entitlement," which leads them to ask teachers more questions and be more active students, causing teachers to favor them. This child-rearing approach, which creates positive interactions in the classroom environment, is in contrast with the natural growth approach to child-rearing. In this approach, which is more common among working-class families, parents do not focus on developing their individual children''s special talents, and they speak to their children in directives. As a result, children raised this way are less likely to question or challenge adults, and conflict can arise between home and school child-rearing practices. Children raised this way are less inclined to participate in the classroom and less likely to go out of their way to interact positively with teachers and build relationships. However, the greater freedom of working-class children gives them a broader range of local playmates, closer relationships with cousins and extended family, less sibling rivalry, fewer complaints to their parents of being bored, and fewer parent-child arguments.', 'Wikipedia: Social mobility', 'https://en.wikipedia.org/w/index.php?title=Social_mobility&oldid=1380459640', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'The cultural resources a person has obtained can heavily influence a child''s educational success. Students raised under the concerted cultivation approach have "an emerging sense of entitlement," which leads them to ask teachers more questions and be more active students, causing teachers to favor them. This child-rearing approach, which creates positive interactions in the classroom environment, is in contrast with the natural growth approach to child-rearing. In this approach, which is more common among working-class families, parents do not focus on developing their individual children''s special talents, and they speak to their children in directives. As a result, children raised this way are less likely to question or challenge adults, and conflict can arise between home and school child-rearing practices. Children raised this way are less inclined to participate in the classroom and less likely to go out of their way to interact positively with teachers and build relationships. However, the greater freedom of working-class children gives them a broader range of local playmates, closer relationships with cousins and extended family, less sibling rivalry, fewer complaints to their parents of being bored, and fewer parent-child arguments.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Cultural capital', 'In sociology, cultural capital refers to the social assets of an individual—such as education, knowledge, style of speech, aesthetic preferences, and credentials—that can promote social mobility within a stratified society. Cultural capital functions as a relational resource within systems of exchange and social recognition, encompassing both material and symbolic goods that are considered valuable in a given social context. It has contributed to the accumulation of social status and power and plays a central role in processes of social evaluation and legitimacy. Pierre Bourdieu and Jean-Claude Passeron introduced the concept in the 1970s to explain persistent inequalities in educational achievement. Bourdieu later elaborated the theory in The Forms of Capital (1986), distinguishing three forms: embodied cultural capital, objectified cultural capital, and institutionalized cultural capital. Embodied cultural capital consists of internalized dispositions and competencies; objectified cultural capital refers to cultural goods such as books or artworks; and institutionalized cultural capital is represented by formally recognized credentials and qualifications. Since its introduction, cultural capital has become a foundational concept in sociology and education research. It has been widely applied to analyses of social reproduction, class inequality, and institutional power, while also generating debates regarding its conceptual scope, empirical measurement, and applicability across different social contexts.', 'Wikipedia: Cultural capital', 'https://en.wikipedia.org/w/index.php?title=Cultural_capital&oldid=1372583246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'In sociology, cultural capital refers to the social assets of an individual—such as education, knowledge, style of speech, aesthetic preferences, and credentials—that can promote social mobility within a stratified society. Cultural capital functions as a relational resource within systems of exchange and social recognition, encompassing both material and symbolic goods that are considered valuable in a given social context. It has contributed to the accumulation of social status and power and plays a central role in processes of social evaluation and legitimacy. Pierre Bourdieu and Jean-Claude Passeron introduced the concept in the 1970s to explain persistent inequalities in educational achievement. Bourdieu later elaborated the theory in The Forms of Capital (1986), distinguishing three forms: embodied cultural capital, objectified cultural capital, and institutionalized cultural capital. Embodied cultural capital consists of internalized dispositions and competencies; objectified cultural capital refers to cultural goods such as books or artworks; and institutionalized cultural capital is represented by formally recognized credentials and qualifications. Since its introduction, cultural capital has become a foundational concept in sociology and education research. It has been widely applied to analyses of social reproduction, class inequality, and institutional power, while also generating debates regarding its conceptual scope, empirical measurement, and applicability across different social contexts.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Cultural capital: Origin', 'In "Cultural Reproduction and Social Reproduction" (1977), Pierre Bourdieu and Jean-Claude Passeron introduced cultural capital to explain differences in children''s performance levels and academic achievement within the French educational system in the 1960s. Bourdieu further developed the concept in his essay "The Forms of Capital" (1985) and in his book The State Nobility: Élite Schools in the Field of Power (1996). In the essay, Bourdieu lists cultural capital among two other categories of capital: economic capital, which refers to the command of economic resources (money, assets, property); and social capital, which is the actual and potential resources linked to the possession of a durable network of institutionalized relationships of mutual acquaintance and recognition.', 'Wikipedia: Cultural capital', 'https://en.wikipedia.org/w/index.php?title=Cultural_capital&oldid=1372583246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'In "Cultural Reproduction and Social Reproduction" (1977), Pierre Bourdieu and Jean-Claude Passeron introduced cultural capital to explain differences in children''s performance levels and academic achievement within the French educational system in the 1960s. Bourdieu further developed the concept in his essay "The Forms of Capital" (1985) and in his book The State Nobility: Élite Schools in the Field of Power (1996). In the essay, Bourdieu lists cultural capital among two other categories of capital: economic capital, which refers to the command of economic resources (money, assets, property); and social capital, which is the actual and potential resources linked to the possession of a durable network of institutionalized relationships of mutual acquaintance and recognition.');
