insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Cultural capital: Embodied cultural capital', 'Embodied cultural capital comprises the knowledge, skills, dispositions, and competencies that are internalized through socialization and education. Unlike economic capital, it is not directly transferable between individuals, but is acquired over time as it becomes incorporated into a person''s habitus (i.e., durable ways of thinking, perceiving, and acting). Because embodied cultural capital is accumulated through long-term exposure to cultural environments, it reflects both conscious learning and tacit absorption of norms, values, and cultural expectations. Linguistic cultural capital, for example, refers to mastery of language, communication styles, and culturally valued forms of expression. The embodied cultural capital that shapes a person''s modes of self-presentation, interaction, and interpretation is often closely associated with the dominant norms of the national or social culture.', 'Wikipedia: Cultural capital', 'https://en.wikipedia.org/w/index.php?title=Cultural_capital&oldid=1372583246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Embodied cultural capital comprises the knowledge, skills, dispositions, and competencies that are internalized through socialization and education. Unlike economic capital, it is not directly transferable between individuals, but is acquired over time as it becomes incorporated into a person''s habitus (i.e., durable ways of thinking, perceiving, and acting). Because embodied cultural capital is accumulated through long-term exposure to cultural environments, it reflects both conscious learning and tacit absorption of norms, values, and cultural expectations. Linguistic cultural capital, for example, refers to mastery of language, communication styles, and culturally valued forms of expression. The embodied cultural capital that shapes a person''s modes of self-presentation, interaction, and interpretation is often closely associated with the dominant norms of the national or social culture.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Cultural capital: Habitus and field', 'An individual''s cultural capital is closely linked to their habitus (i.e., embodied dispositions and tendencies) and their position within a field (i.e., structured social spaces characterized by power relations and competition). Habitus refers to the durable dispositions inculcated through family background, education, and social experience, which guide perception, judgment, and action. It is shaped by social class, family environment, and everyday social interactions, and may evolve as individuals move between different social positions within a field. In Bourdieu’s framework, a field is a social arena in which individuals and groups compete to define what forms of capital are legitimate and valuable. Because different fields (such as education, art, or politics) recognize and reward different forms of cultural capital, a particular type of capital may be considered legitimate in one context and less valued in another. The process by which certain forms of capital become socially recognized and authoritative is closely related to symbolic capital, or the power to impose recognition and legitimacy within a given social space.', 'Wikipedia: Cultural capital', 'https://en.wikipedia.org/w/index.php?title=Cultural_capital&oldid=1372583246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'An individual''s cultural capital is closely linked to their habitus (i.e., embodied dispositions and tendencies) and their position within a field (i.e., structured social spaces characterized by power relations and competition). Habitus refers to the durable dispositions inculcated through family background, education, and social experience, which guide perception, judgment, and action. It is shaped by social class, family environment, and everyday social interactions, and may evolve as individuals move between different social positions within a field. In Bourdieu’s framework, a field is a social arena in which individuals and groups compete to define what forms of capital are legitimate and valuable. Because different fields (such as education, art, or politics) recognize and reward different forms of cultural capital, a particular type of capital may be considered legitimate in one context and less valued in another. The process by which certain forms of capital become socially recognized and authoritative is closely related to symbolic capital, or the power to impose recognition and legitimacy within a given social space.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Cultural capital: Objectified cultural capital', 'Objectified cultural capital refers to material cultural goods (e.g., works of art, books, scientific instruments, or other cultural artefacts) that can be owned, exchanged, and transferred for economic profit. However, the social and cultural value of these objects depends partly on the holder’s ability to appropriate and interpret them. According to Bourdieu, the mere possession of cultural goods does not automatically confer cultural competence; rather, their meaning and symbolic significance are most accessible to those with the relevant embodied cultural capital, including the knowledge and dispositions necessary for interpretation. In this sense, while objectified cultural capital may circulate through market exchange, its cultural significance remains tied to embodied capacities.', 'Wikipedia: Cultural capital', 'https://en.wikipedia.org/w/index.php?title=Cultural_capital&oldid=1372583246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Objectified cultural capital refers to material cultural goods (e.g., works of art, books, scientific instruments, or other cultural artefacts) that can be owned, exchanged, and transferred for economic profit. However, the social and cultural value of these objects depends partly on the holder’s ability to appropriate and interpret them. According to Bourdieu, the mere possession of cultural goods does not automatically confer cultural competence; rather, their meaning and symbolic significance are most accessible to those with the relevant embodied cultural capital, including the knowledge and dispositions necessary for interpretation. In this sense, while objectified cultural capital may circulate through market exchange, its cultural significance remains tied to embodied capacities.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Cultural capital: Institutionalized cultural capital', 'Institutionalized cultural capital comprises an institution''s formal recognition of a person''s cultural capital, usually academic credentials or professional qualifications. Institutionalized cultural capital has an important role in the labor market (a job), wherein it allows the expression of the person''s array of cultural capital as qualitative and quantitative measurements that can be compared with those of other people. The institutional recognition facilitates the conversion of cultural capital into economic capital by serving as a heuristic (practical solution) with which the seller can describe their cultural capital to the buyer.', 'Wikipedia: Cultural capital', 'https://en.wikipedia.org/w/index.php?title=Cultural_capital&oldid=1372583246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Institutionalized cultural capital comprises an institution''s formal recognition of a person''s cultural capital, usually academic credentials or professional qualifications. Institutionalized cultural capital has an important role in the labor market (a job), wherein it allows the expression of the person''s array of cultural capital as qualitative and quantitative measurements that can be compared with those of other people. The institutional recognition facilitates the conversion of cultural capital into economic capital by serving as a heuristic (practical solution) with which the seller can describe their cultural capital to the buyer.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Cultural capital: Theoretical research', 'The concept of cultural capital has generated extensive theoretical and empirical scholarship across sociology, education, and cultural studies. Although most frequently applied in analyses of educational inequality, researchers have extended Bourdieu’s framework to examine broader processes of social stratification, institutional power, and cultural legitimacy. Scholarly engagement with cultural capital has generally taken three forms: application, refinement, and critique. Some researchers employ the concept as an explanatory framework for understanding patterns of social reproduction. Others build upon or modify Bourdieu’s original formulation to account for contemporary cultural dynamics. Still others question aspects of its conceptual clarity, empirical measurement, or scope. While education remains the primary domain in which cultural capital theory has been operationalized, subsequent research has broadened its relevance to other forms of inequality and institutional contexts.', 'Wikipedia: Cultural capital', 'https://en.wikipedia.org/w/index.php?title=Cultural_capital&oldid=1372583246', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'The concept of cultural capital has generated extensive theoretical and empirical scholarship across sociology, education, and cultural studies. Although most frequently applied in analyses of educational inequality, researchers have extended Bourdieu’s framework to examine broader processes of social stratification, institutional power, and cultural legitimacy. Scholarly engagement with cultural capital has generally taken three forms: application, refinement, and critique. Some researchers employ the concept as an explanatory framework for understanding patterns of social reproduction. Others build upon or modify Bourdieu’s original formulation to account for contemporary cultural dynamics. Still others question aspects of its conceptual clarity, empirical measurement, or scope. While education remains the primary domain in which cultural capital theory has been operationalized, subsequent research has broadened its relevance to other forms of inequality and institutional contexts.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social capital', 'Social capital is a concept used in sociology and economics to define networks of relationships which are productive towards advancing the goals of individuals and groups. It involves the effective functioning of social groups through interpersonal relationships, a shared sense of identity, a shared understanding, shared norms, shared values, trust, cooperation, and reciprocity. Some have described it as a form of capital that produces public goods for a common purpose, although this does not align with how it has been measured. Social capital has been used to explain the improved performance of diverse groups, the growth of entrepreneurial firms, superior managerial performance, enhanced supply chain relations, the value derived from strategic alliances, and the evolution of communities.', 'Wikipedia: Social capital', 'https://en.wikipedia.org/w/index.php?title=Social_capital&oldid=1376521759', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Social capital is a concept used in sociology and economics to define networks of relationships which are productive towards advancing the goals of individuals and groups. It involves the effective functioning of social groups through interpersonal relationships, a shared sense of identity, a shared understanding, shared norms, shared values, trust, cooperation, and reciprocity. Some have described it as a form of capital that produces public goods for a common purpose, although this does not align with how it has been measured. Social capital has been used to explain the improved performance of diverse groups, the growth of entrepreneurial firms, superior managerial performance, enhanced supply chain relations, the value derived from strategic alliances, and the evolution of communities.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social capital: Definitions and forms', 'Social capital has multiple definitions, interpretations, and uses. David Halpern argues that the popularity of social capital for policymakers is linked to the concept''s duality, coming because "it has a hard nosed economic feel while restating the importance of the social." For researchers, the term is popular partly due to the broad range of outcomes it can explain; the multiplicity of uses for social capital has led to a multiplicity of definitions. Social capital involves networks of relationships based on trust that allows individuals and institutions to access resources needed. Social capital has been used at various times to explain superior managerial performance, the growth of entrepreneurial firms, improved performance of functionally diverse groups, the value derived from strategic alliances, and enhanced supply-chain relations. "A resource that actors derive from specific social structures and then use to pursue their interests; it is created by changes in the relationship among actors" (Baker 1990, p. 619).', 'Wikipedia: Social capital', 'https://en.wikipedia.org/w/index.php?title=Social_capital&oldid=1376521759', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Social capital has multiple definitions, interpretations, and uses. David Halpern argues that the popularity of social capital for policymakers is linked to the concept''s duality, coming because "it has a hard nosed economic feel while restating the importance of the social." For researchers, the term is popular partly due to the broad range of outcomes it can explain; the multiplicity of uses for social capital has led to a multiplicity of definitions. Social capital involves networks of relationships based on trust that allows individuals and institutions to access resources needed. Social capital has been used at various times to explain superior managerial performance, the growth of entrepreneurial firms, improved performance of functionally diverse groups, the value derived from strategic alliances, and enhanced supply-chain relations. "A resource that actors derive from specific social structures and then use to pursue their interests; it is created by changes in the relationship among actors" (Baker 1990, p. 619).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social capital: Definitions and forms', 'Early attempts to define social capital focused on the degree to which social capital serves as a resource – be it for public good or private benefit. Robert D. Putnam (1993) suggested that social capital would facilitate co-operation and mutually supportive relations in communities and nations and would therefore be a valuable means of combating many of the social disorders inherent in modern societies, for example crime. In contrast, others focus on the private benefits derived from the web of social relationships in which individual actors find themselves. This is reflected in Nan Lin''s concept of social capital as "Investment in social relations with expected returns in the marketplace." This may subsume the concepts of some others such as Bourdieu, Flap and Eriksson. Newton (1997) treats social capital as a subjective phenomenon formed by values and attitudes that influence interactions. Nahapiet and Ghoshal (1998), in their examination of the role of social capital in the creation of intellectual capital, suggest that social capital should be considered in terms of three clusters: structural, relational, and cognitive.', 'Wikipedia: Social capital', 'https://en.wikipedia.org/w/index.php?title=Social_capital&oldid=1376521759', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Early attempts to define social capital focused on the degree to which social capital serves as a resource – be it for public good or private benefit. Robert D. Putnam (1993) suggested that social capital would facilitate co-operation and mutually supportive relations in communities and nations and would therefore be a valuable means of combating many of the social disorders inherent in modern societies, for example crime. In contrast, others focus on the private benefits derived from the web of social relationships in which individual actors find themselves. This is reflected in Nan Lin''s concept of social capital as "Investment in social relations with expected returns in the marketplace." This may subsume the concepts of some others such as Bourdieu, Flap and Eriksson. Newton (1997) treats social capital as a subjective phenomenon formed by values and attitudes that influence interactions. Nahapiet and Ghoshal (1998), in their examination of the role of social capital in the creation of intellectual capital, suggest that social capital should be considered in terms of three clusters: structural, relational, and cognitive.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social capital: Definitional issues', 'A number of scholars have raised concerns about the imprecision in defining social capital. Portes (2000), for example, notes that the term has become so widely used, including in mainstream media, that "the point is approaching at which social capital comes to be applied to so many events and in so many different contexts as to lose any distinct meaning." The term capital is used by analogy with other forms of economic capital, as social capital is argued to have similar (although less measurable) benefits. However, the analogy may be misleading in that, unlike financial forms of capital, social capital is not depleted by use; instead, it is depleted by non-use (use it or lose it). In this respect, it is similar to the economic concept of human capital.', 'Wikipedia: Social capital', 'https://en.wikipedia.org/w/index.php?title=Social_capital&oldid=1376521759', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'A number of scholars have raised concerns about the imprecision in defining social capital. Portes (2000), for example, notes that the term has become so widely used, including in mainstream media, that "the point is approaching at which social capital comes to be applied to so many events and in so many different contexts as to lose any distinct meaning." The term capital is used by analogy with other forms of economic capital, as social capital is argued to have similar (although less measurable) benefits. However, the analogy may be misleading in that, unlike financial forms of capital, social capital is not depleted by use; instead, it is depleted by non-use (use it or lose it). In this respect, it is similar to the economic concept of human capital.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social capital: Definitional issues', 'Robison, Schmid, and Siles (2002) review various definitions of social capital and conclude that many do not satisfy the formal requirements of a definition. They assert that definitions must be of the form A=B, while many explanations of social capital describe what it can be used to achieve, where it resides, how it can be created, or what it can transform. In addition, they argue that many proposed definitions of social capital fail to satisfy the requirements of capital. They propose that social capital be defined as sympathy: the object of another''s sympathy has social capital; those who have sympathy for others provide social capital. This proposition appears to follow Adam Smith, Theory of Moral Sentiments to some degree, but Smith''s conceptualization of sympathy (particularly in the first two chapters of this work) appear more concerned with the roles of acceptance or congruence – in ethics or virtue – in evaluating an individual''s ''propriety of action''. Social capital is different from the economic theory of social capitalism, which challenges the idea that socialism and capitalism are mutually exclusive.', 'Wikipedia: Social capital', 'https://en.wikipedia.org/w/index.php?title=Social_capital&oldid=1376521759', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Robison, Schmid, and Siles (2002) review various definitions of social capital and conclude that many do not satisfy the formal requirements of a definition. They assert that definitions must be of the form A=B, while many explanations of social capital describe what it can be used to achieve, where it resides, how it can be created, or what it can transform. In addition, they argue that many proposed definitions of social capital fail to satisfy the requirements of capital. They propose that social capital be defined as sympathy: the object of another''s sympathy has social capital; those who have sympathy for others provide social capital. This proposition appears to follow Adam Smith, Theory of Moral Sentiments to some degree, but Smith''s conceptualization of sympathy (particularly in the first two chapters of this work) appear more concerned with the roles of acceptance or congruence – in ethics or virtue – in evaluating an individual''s ''propriety of action''. Social capital is different from the economic theory of social capitalism, which challenges the idea that socialism and capitalism are mutually exclusive.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social capital: Forms of capital (Bourdieu)', 'In The Forms of Capital, Pierre Bourdieu distinguishes between three forms of capital: economic capital, cultural capital and social capital. He defines social capital as "the aggregate of the actual or potential resources which are linked to possession of a durable network of more or less institutionalized relationships of mutual acquaintance and recognition." His treatment of the concept is instrumental, focusing on the advantages to possessors of social capital and the "deliberate construction of sociability for the purpose of creating this resource." Quite contrary to Putnam''s positive view of social capital, Bourdieu employs the concept to demonstrate a mechanism for the generational reproduction of inequality. Bourdieu thus points out that the wealthy and powerful use their "old boys network" or other social capital to maintain advantages for themselves, their social class, and their children.', 'Wikipedia: Social capital', 'https://en.wikipedia.org/w/index.php?title=Social_capital&oldid=1376521759', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'In The Forms of Capital, Pierre Bourdieu distinguishes between three forms of capital: economic capital, cultural capital and social capital. He defines social capital as "the aggregate of the actual or potential resources which are linked to possession of a durable network of more or less institutionalized relationships of mutual acquaintance and recognition." His treatment of the concept is instrumental, focusing on the advantages to possessors of social capital and the "deliberate construction of sociability for the purpose of creating this resource." Quite contrary to Putnam''s positive view of social capital, Bourdieu employs the concept to demonstrate a mechanism for the generational reproduction of inequality. Bourdieu thus points out that the wealthy and powerful use their "old boys network" or other social capital to maintain advantages for themselves, their social class, and their children.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social capital: Norms of trust and reciprocity (Sander, Putnam, Coleman)', 'Thomas Sander defines it as "the collective value of all social networks (who people know), and the inclinations that arise from these networks to do things for each other (norms of reciprocity)." Social capital, in this view, emphasizes "specific benefits that flow from the trust, reciprocity, information, and cooperation associated with social networks." It "creates value for the people who are connected, and for bystanders as well." Meanwhile, negative norms of reciprocity serve as disincentives for detrimental and violent behaviors. James Coleman defined social capital functionally as "a variety of entities with two elements in common: they all consist of some aspect of social structure, and they facilitate certain actions of actors...within the structure" – that is, social capital is anything that facilitates individual or collective action, generated by networks of relationships, reciprocity, trust, and social norms. In Coleman''s conception, social capital is a neutral resource that facilitates any manner of action, but whether society is better off as a result depends entirely on the individual uses to which it is put.', 'Wikipedia: Social capital', 'https://en.wikipedia.org/w/index.php?title=Social_capital&oldid=1376521759', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Thomas Sander defines it as "the collective value of all social networks (who people know), and the inclinations that arise from these networks to do things for each other (norms of reciprocity)." Social capital, in this view, emphasizes "specific benefits that flow from the trust, reciprocity, information, and cooperation associated with social networks." It "creates value for the people who are connected, and for bystanders as well." Meanwhile, negative norms of reciprocity serve as disincentives for detrimental and violent behaviors. James Coleman defined social capital functionally as "a variety of entities with two elements in common: they all consist of some aspect of social structure, and they facilitate certain actions of actors...within the structure" – that is, social capital is anything that facilitates individual or collective action, generated by networks of relationships, reciprocity, trust, and social norms. In Coleman''s conception, social capital is a neutral resource that facilitates any manner of action, but whether society is better off as a result depends entirely on the individual uses to which it is put.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Social capital: Norms of trust and reciprocity (Sander, Putnam, Coleman)', 'According to Robert D. Putnam, social capital refers to "connections among individuals – social networks and the norms of reciprocity and trustworthiness that arise from them." In the view of Putnam and his followers, social capital is a key component to building and maintaining democracy. Putnam says that social capital is declining in the United States. This is seen in lower levels of trust in government and lower levels of civic participation. Putnam also suggests that a root cause of the decline in social capital is women''s entry into the workforce, which could correlate with time restraints that inhibit civic organizational involvement like parent-teacher associations. Technological transformation of leisure (e.g., television) is another cause of declining social capital, as stated by Putnam. This offered a reference point from which several studies assessed social capital measurements by how media is engaged strategically to build social capital.', 'Wikipedia: Social capital', 'https://en.wikipedia.org/w/index.php?title=Social_capital&oldid=1376521759', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'According to Robert D. Putnam, social capital refers to "connections among individuals – social networks and the norms of reciprocity and trustworthiness that arise from them." In the view of Putnam and his followers, social capital is a key component to building and maintaining democracy. Putnam says that social capital is declining in the United States. This is seen in lower levels of trust in government and lower levels of civic participation. Putnam also suggests that a root cause of the decline in social capital is women''s entry into the workforce, which could correlate with time restraints that inhibit civic organizational involvement like parent-teacher associations. Technological transformation of leisure (e.g., television) is another cause of declining social capital, as stated by Putnam. This offered a reference point from which several studies assessed social capital measurements by how media is engaged strategically to build social capital.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Demographic transition', 'Demographic transition is a phenomenon and theory in the social sciences (especially demography) referring to the historical shift from high to low rates of birth and death, as societies attain several attributes: more technology, education (especially for women), and economic development. The demographic transition has occurred in most of the world over the past two centuries, bringing the unprecedented population growth of the post-Malthusian period, and then reducing birth rates and population growth significantly in all regions of the world. The demographic transition strengthens the economic growth process through three changes: reduced dilution of capital and land stock; increased investment in human capital; and increased size of the labor force relative to the total population, along with a changed distribution of population age. Although this shift has occurred in many industrialized countries, the theory and model are often imprecise when applied to individual countries, because of specific social, political, and economic factors that affect particular populations.', 'Wikipedia: Demographic transition', 'https://en.wikipedia.org/w/index.php?title=Demographic_transition&oldid=1377297895', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Demographic transition is a phenomenon and theory in the social sciences (especially demography) referring to the historical shift from high to low rates of birth and death, as societies attain several attributes: more technology, education (especially for women), and economic development. The demographic transition has occurred in most of the world over the past two centuries, bringing the unprecedented population growth of the post-Malthusian period, and then reducing birth rates and population growth significantly in all regions of the world. The demographic transition strengthens the economic growth process through three changes: reduced dilution of capital and land stock; increased investment in human capital; and increased size of the labor force relative to the total population, along with a changed distribution of population age. Although this shift has occurred in many industrialized countries, the theory and model are often imprecise when applied to individual countries, because of specific social, political, and economic factors that affect particular populations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Demographic transition', 'Nevertheless, the existence of some type of demographic transition is widely accepted because of the well-established historical correlation between two factors: dropping fertility rates, and social and economic development. Scholars debate whether industrialization and higher incomes lead to lower population, or vice versa. Scholars also debate to what extent various proposed and sometimes interrelated factors are involved—factors such as higher per capita income, lower mortality, old-age security, and increased demand for human capital. Human capital gradually increased during the second stage of the Industrial Revolution, which coincided with the demographic transition. The increasing role of human capital in the production process led families to invest this capital in children, which may have been the beginning of the demographic transition.', 'Wikipedia: Demographic transition', 'https://en.wikipedia.org/w/index.php?title=Demographic_transition&oldid=1377297895', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Nevertheless, the existence of some type of demographic transition is widely accepted because of the well-established historical correlation between two factors: dropping fertility rates, and social and economic development. Scholars debate whether industrialization and higher incomes lead to lower population, or vice versa. Scholars also debate to what extent various proposed and sometimes interrelated factors are involved—factors such as higher per capita income, lower mortality, old-age security, and increased demand for human capital. Human capital gradually increased during the second stage of the Industrial Revolution, which coincided with the demographic transition. The increasing role of human capital in the production process led families to invest this capital in children, which may have been the beginning of the demographic transition.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Demographic transition: Overview', 'In Stage 1, that of pre-industrial society, death rates and birth rates are high and roughly in balance. All human populations are believed to have had this balance until the late 18th century, when it ended in Western Europe. In fact, growth rates were less than 0.05% since at least the Agricultural Revolution, more than 10,000 years ago. Population growth is typically very slow during this stage because society is constrained by the available food supply; therefore, unless society develops new technologies to increase food production (e.g., discovers new sources of food, or achieves higher crop yields), any fluctuation in birth rates is soon matched by death rates.', 'Wikipedia: Demographic transition', 'https://en.wikipedia.org/w/index.php?title=Demographic_transition&oldid=1377297895', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'In Stage 1, that of pre-industrial society, death rates and birth rates are high and roughly in balance. All human populations are believed to have had this balance until the late 18th century, when it ended in Western Europe. In fact, growth rates were less than 0.05% since at least the Agricultural Revolution, more than 10,000 years ago. Population growth is typically very slow during this stage because society is constrained by the available food supply; therefore, unless society develops new technologies to increase food production (e.g., discovers new sources of food, or achieves higher crop yields), any fluctuation in birth rates is soon matched by death rates.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Demographic transition: Overview', 'In Stage 2, that of a developing country, death rates quickly drop because of improvements in food supply and sanitation, which increase life expectancy and reduce disease. Improvements specific to food supply typically include selective breeding, in addition to crop rotation and farming techniques. Numerous improvements in public health reduce mortality, especially for children. Before the mid-20th century, these improvements in public health primarily concerned food handling, water supply, sewage, and personal hygiene. An often-cited variable is the increase in female literacy, in combination with public-health education programs that emerged in the late 19th and early 20th centuries. In Europe, the decline in death rates started in the late 18th century in northwestern Europe, and it spread to the south and east over approximately the next 100 years. Without a corresponding fall in birth rates, this change produces an imbalance, and countries in this stage experience a large increase in population.', 'Wikipedia: Demographic transition', 'https://en.wikipedia.org/w/index.php?title=Demographic_transition&oldid=1377297895', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'In Stage 2, that of a developing country, death rates quickly drop because of improvements in food supply and sanitation, which increase life expectancy and reduce disease. Improvements specific to food supply typically include selective breeding, in addition to crop rotation and farming techniques. Numerous improvements in public health reduce mortality, especially for children. Before the mid-20th century, these improvements in public health primarily concerned food handling, water supply, sewage, and personal hygiene. An often-cited variable is the increase in female literacy, in combination with public-health education programs that emerged in the late 19th and early 20th centuries. In Europe, the decline in death rates started in the late 18th century in northwestern Europe, and it spread to the south and east over approximately the next 100 years. Without a corresponding fall in birth rates, this change produces an imbalance, and countries in this stage experience a large increase in population.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Demographic transition: Overview', 'In Stage 3, birth rates fall because of various fertility factors, such as the following: access to contraception; increases in wages; urbanization; a reduction in subsistence agriculture; an increase in the status and education of women; a reduction in the value of children''s work; an increase in parental investment in the education of children; and other social changes. Population growth begins to level off. The birth-rate decline in developed countries started in the late 19th century in Northern Europe. While improvements in contraception play a role in birth-rate decline, contraceptives were not generally available nor widely used in the 19th century. As a result, they probably played an insignificant role in the decline at that time. Birth-rate decline is also caused by a transition in values, not just the availability of contraceptives.', 'Wikipedia: Demographic transition', 'https://en.wikipedia.org/w/index.php?title=Demographic_transition&oldid=1377297895', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'In Stage 3, birth rates fall because of various fertility factors, such as the following: access to contraception; increases in wages; urbanization; a reduction in subsistence agriculture; an increase in the status and education of women; a reduction in the value of children''s work; an increase in parental investment in the education of children; and other social changes. Population growth begins to level off. The birth-rate decline in developed countries started in the late 19th century in Northern Europe. While improvements in contraception play a role in birth-rate decline, contraceptives were not generally available nor widely used in the 19th century. As a result, they probably played an insignificant role in the decline at that time. Birth-rate decline is also caused by a transition in values, not just the availability of contraceptives.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Demographic transition: Overview', 'In Stage 4, birth and death rates are both low. Birth rates may drop to well below replacement level, as has happened in countries such as Germany, Italy, and Japan; this drop leads to a shrinking population, which threatens many industries that rely on population growth. As the large group born during Stage 2 ages, an economic burden is placed on the shrinking working population. Death rates may remain consistently low or increase slightly because of increases in lifestyle diseases due to several factors: low exercise levels, high obesity rates, and an ageing population in developed countries. By the late 20th century, birth rates and death rates in developed countries had levelled off at lower rates. A "Stage 5" is broken out from Stage 4 by some scholars, with below-replacement fertility levels. Other scholars hypothesise a different "Stage 5" involving an increase in fertility.', 'Wikipedia: Demographic transition', 'https://en.wikipedia.org/w/index.php?title=Demographic_transition&oldid=1377297895', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'In Stage 4, birth and death rates are both low. Birth rates may drop to well below replacement level, as has happened in countries such as Germany, Italy, and Japan; this drop leads to a shrinking population, which threatens many industries that rely on population growth. As the large group born during Stage 2 ages, an economic burden is placed on the shrinking working population. Death rates may remain consistently low or increase slightly because of increases in lifestyle diseases due to several factors: low exercise levels, high obesity rates, and an ageing population in developed countries. By the late 20th century, birth rates and death rates in developed countries had levelled off at lower rates. A "Stage 5" is broken out from Stage 4 by some scholars, with below-replacement fertility levels. Other scholars hypothesise a different "Stage 5" involving an increase in fertility.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Demographic transition: Overview', 'As with all models, the Demographic Transition Model (DTM) is an idealised picture of population change in these countries. The model is a generalisation that applies to these countries as a group, and it may not accurately describe each specific case. The extent to which the model applies to less-developed societies remains to be seen. Many countries—such as China, Brazil, and Thailand—have passed through the DTM very quickly because of rapid social and economic change. Some countries, particularly in Africa, appear to be stuck in the second stage because of stagnant development, as well as the effects of insufficient investments and research into tropical diseases such as malaria and AIDS, to some extent.', 'Wikipedia: Demographic transition', 'https://en.wikipedia.org/w/index.php?title=Demographic_transition&oldid=1377297895', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'As with all models, the Demographic Transition Model (DTM) is an idealised picture of population change in these countries. The model is a generalisation that applies to these countries as a group, and it may not accurately describe each specific case. The extent to which the model applies to less-developed societies remains to be seen. Many countries—such as China, Brazil, and Thailand—have passed through the DTM very quickly because of rapid social and economic change. Some countries, particularly in Africa, appear to be stuck in the second stage because of stagnant development, as well as the effects of insufficient investments and research into tropical diseases such as malaria and AIDS, to some extent.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Demographic transition: Stage 1', 'In pre-industrial society, death rates and birth rates were both high—fluctuating rapidly according to natural events, such as drought and disease, to produce a relatively constant and young population. Family planning and contraception were virtually nonexistent; therefore, birth rates were essentially limited only by the ability of women to bear children. Emigration depressed death rates in some special cases (for example, Europe and particularly the eastern United States during the 19th century). But overall, death rates tended to match birth rates, often exceeding 40 per 1000 per year. Children contributed to the household''s economy from an early age in multiple ways: carrying water, firewood, and messages; caring for younger siblings; sweeping; washing dishes; preparing food; and working in the fields. Raising a child cost little more than feeding them; there were no education or entertainment expenses. Thus, the total cost of raising children barely exceeded their contribution to the household. Moreover, as children grew into adulthood, they became a major input to the family business, mainly farming; they were also the primary form of insurance for adults in old age. In India, an adult son was frequently the only thing that prevented a widow from falling into destitution. While death rates remained high, there was no question about the need for children, even if a means to prevent their birth had existed.', 'Wikipedia: Demographic transition', 'https://en.wikipedia.org/w/index.php?title=Demographic_transition&oldid=1377297895', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'In pre-industrial society, death rates and birth rates were both high—fluctuating rapidly according to natural events, such as drought and disease, to produce a relatively constant and young population. Family planning and contraception were virtually nonexistent; therefore, birth rates were essentially limited only by the ability of women to bear children. Emigration depressed death rates in some special cases (for example, Europe and particularly the eastern United States during the 19th century). But overall, death rates tended to match birth rates, often exceeding 40 per 1000 per year. Children contributed to the household''s economy from an early age in multiple ways: carrying water, firewood, and messages; caring for younger siblings; sweeping; washing dishes; preparing food; and working in the fields. Raising a child cost little more than feeding them; there were no education or entertainment expenses. Thus, the total cost of raising children barely exceeded their contribution to the household. Moreover, as children grew into adulthood, they became a major input to the family business, mainly farming; they were also the primary form of insurance for adults in old age. In India, an adult son was frequently the only thing that prevented a widow from falling into destitution. While death rates remained high, there was no question about the need for children, even if a means to prevent their birth had existed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Health equity', 'Health equity is social equity in health. Disparities in health outcomes can be related to differences in access to social determinants of health, specifically from wealth, power and prestige. Individuals who have consistently been deprived of these three determinants are significantly disadvantaged from health inequities, and face worse health outcomes than those who are able to access certain resources. This is especially important in areas with increased diversity across social, ethnic, and racial groups, as underrepresentation in healthcare systems is a global issue. In order to achieve health equity, resources must be allocated based on an individual need-based principle. Health equity is distinct from formal equal opportunity, such as simply providing every individual with equal access to health care. Health equity is also connected with Scientific Equity, which describes the scientific methods by which to achieve Health Equity. According to the World Health Organization, "Health is a state of complete physical, mental and social well-being and not merely the absence of disease or infirmity". The quality of health and how health is distributed among economic and social status in a society can provide insight into the level of development within that society. Health is a basic human right and human need, and all human rights are interconnected. Thus, health must be discussed along with all other basic human rights.', 'Wikipedia: Health equity', 'https://en.wikipedia.org/w/index.php?title=Health_equity&oldid=1378982805', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Health equity is social equity in health. Disparities in health outcomes can be related to differences in access to social determinants of health, specifically from wealth, power and prestige. Individuals who have consistently been deprived of these three determinants are significantly disadvantaged from health inequities, and face worse health outcomes than those who are able to access certain resources. This is especially important in areas with increased diversity across social, ethnic, and racial groups, as underrepresentation in healthcare systems is a global issue. In order to achieve health equity, resources must be allocated based on an individual need-based principle. Health equity is distinct from formal equal opportunity, such as simply providing every individual with equal access to health care. Health equity is also connected with Scientific Equity, which describes the scientific methods by which to achieve Health Equity. According to the World Health Organization, "Health is a state of complete physical, mental and social well-being and not merely the absence of disease or infirmity". The quality of health and how health is distributed among economic and social status in a society can provide insight into the level of development within that society. Health is a basic human right and human need, and all human rights are interconnected. Thus, health must be discussed along with all other basic human rights.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Health equity', 'Health equity is defined by the CDC as "the state in which everyone has a fair and just opportunity to attain their highest level of health". It is closely associated with the social justice movement, with good health considered a fundamental human right. These inequities may include differences in the "presence of disease, health outcomes, or access to health care" between populations with a different race, ethnicity, gender, sexual orientation, disability, or socioeconomic status.', 'Wikipedia: Health equity', 'https://en.wikipedia.org/w/index.php?title=Health_equity&oldid=1378982805', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Health equity is defined by the CDC as "the state in which everyone has a fair and just opportunity to attain their highest level of health". It is closely associated with the social justice movement, with good health considered a fundamental human right. These inequities may include differences in the "presence of disease, health outcomes, or access to health care" between populations with a different race, ethnicity, gender, sexual orientation, disability, or socioeconomic status.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Health equity', 'Health inequity differs from health inequality in that the latter term is used in a number of countries to refer to those instances whereby the health of two demographic groups (not necessarily ethnic or racial groups) differs despite similar access to health care services. It can be further described as differences in health that are avoidable, unfair, and unjust, and cannot be explained by natural causes, such as biology, or differences in choice. Thus, if one population dies younger than another because of genetic differences, which is a non-remediable/controllable factor, the situation would be classified as a health inequality. Conversely, if a population has a lower life expectancy due to lack of access to medications, the situation would be classified as a health inequity. These inequities may include differences in the "presence of disease, health outcomes, or access to health care". Although, it is important to recognize the difference in health equity and equality, as having equality in health is essential to begin achieving health equity. The importance of equitable access to healthcare has been cited as crucial to achieving many of the Millennium Development Goals.', 'Wikipedia: Health equity', 'https://en.wikipedia.org/w/index.php?title=Health_equity&oldid=1378982805', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Health inequity differs from health inequality in that the latter term is used in a number of countries to refer to those instances whereby the health of two demographic groups (not necessarily ethnic or racial groups) differs despite similar access to health care services. It can be further described as differences in health that are avoidable, unfair, and unjust, and cannot be explained by natural causes, such as biology, or differences in choice. Thus, if one population dies younger than another because of genetic differences, which is a non-remediable/controllable factor, the situation would be classified as a health inequality. Conversely, if a population has a lower life expectancy due to lack of access to medications, the situation would be classified as a health inequity. These inequities may include differences in the "presence of disease, health outcomes, or access to health care". Although, it is important to recognize the difference in health equity and equality, as having equality in health is essential to begin achieving health equity. The importance of equitable access to healthcare has been cited as crucial to achieving many of the Millennium Development Goals.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Health equity: Socioeconomic status', 'Socioeconomic status is both a strong predictor of health, and a key factor underlying health inequities across populations. Poor socioeconomic status has the capacity to profoundly limit the capabilities of an individual or population, manifesting itself through deficiencies in both financial and social capital. It is clear how a lack of financial capital can compromise the capacity to maintain good health. Income is an important determinant of access to healthcare resources. Because one''s job or career is a primary conduit for both financial and social capital, work is an important, yet underrepresented, factor in health inequities research and prevention efforts. There are many ways that a job can affect one''s health, such as the job''s physical demands, exposure to hazards, mechanisms of employment, compensation and benefits, and availability of health and safety programs. In addition, those who are in steady jobs are less likely to face poverty and its implications and more likely to have access to health care. Maintenance of good health through the utilization of proper healthcare resources can be quite costly and therefore unaffordable to certain populations.', 'Wikipedia: Health equity', 'https://en.wikipedia.org/w/index.php?title=Health_equity&oldid=1378982805', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Socioeconomic status is both a strong predictor of health, and a key factor underlying health inequities across populations. Poor socioeconomic status has the capacity to profoundly limit the capabilities of an individual or population, manifesting itself through deficiencies in both financial and social capital. It is clear how a lack of financial capital can compromise the capacity to maintain good health. Income is an important determinant of access to healthcare resources. Because one''s job or career is a primary conduit for both financial and social capital, work is an important, yet underrepresented, factor in health inequities research and prevention efforts. There are many ways that a job can affect one''s health, such as the job''s physical demands, exposure to hazards, mechanisms of employment, compensation and benefits, and availability of health and safety programs. In addition, those who are in steady jobs are less likely to face poverty and its implications and more likely to have access to health care. Maintenance of good health through the utilization of proper healthcare resources can be quite costly and therefore unaffordable to certain populations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Health equity: Socioeconomic status', 'In China, for instance, the collapse of the Cooperative Medical System left many of the rural poor uninsured and unable to access the resources necessary to maintain good health. Increases in the cost of medical treatment made healthcare increasingly unaffordable for these populations. This issue was further perpetuated by the rising income inequality in the Chinese population. Poor Chinese were often unable to undergo necessary hospitalization and failed to complete treatment regimens, resulting in poorer health outcomes. Similarly, in Tanzania, it was demonstrated that wealthier families were far more likely to bring their children to a healthcare provider: a significant step towards stronger healthcare. Unequal income distribution itself can be a cause of poorer health for a society as a result of "underinvestment in social goods, such as public education and health care; disruption of social cohesion and the erosion of social capital".', 'Wikipedia: Health equity', 'https://en.wikipedia.org/w/index.php?title=Health_equity&oldid=1378982805', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'In China, for instance, the collapse of the Cooperative Medical System left many of the rural poor uninsured and unable to access the resources necessary to maintain good health. Increases in the cost of medical treatment made healthcare increasingly unaffordable for these populations. This issue was further perpetuated by the rising income inequality in the Chinese population. Poor Chinese were often unable to undergo necessary hospitalization and failed to complete treatment regimens, resulting in poorer health outcomes. Similarly, in Tanzania, it was demonstrated that wealthier families were far more likely to bring their children to a healthcare provider: a significant step towards stronger healthcare. Unequal income distribution itself can be a cause of poorer health for a society as a result of "underinvestment in social goods, such as public education and health care; disruption of social cohesion and the erosion of social capital".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Health equity: Socioeconomic status', 'The role of socioeconomic status in health equity extends beyond simple monetary restrictions on an individual''s purchasing power. In fact, social capital plays a significant role in the health of individuals and their communities. It has been shown that those who are better connected to the resources provided by the individuals and communities around them (those with more social capital) live longer lives. The segregation of communities on the basis of income occurs in nations worldwide and has a significant impact on quality of health as a result of a decrease in social capital for those trapped in poor neighborhoods. Social interventions, which seek to improve healthcare by enhancing the social resources of a community, are therefore an effective component of campaigns to improve a community''s health.', 'Wikipedia: Health equity', 'https://en.wikipedia.org/w/index.php?title=Health_equity&oldid=1378982805', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'The role of socioeconomic status in health equity extends beyond simple monetary restrictions on an individual''s purchasing power. In fact, social capital plays a significant role in the health of individuals and their communities. It has been shown that those who are better connected to the resources provided by the individuals and communities around them (those with more social capital) live longer lives. The segregation of communities on the basis of income occurs in nations worldwide and has a significant impact on quality of health as a result of a decrease in social capital for those trapped in poor neighborhoods. Social interventions, which seek to improve healthcare by enhancing the social resources of a community, are therefore an effective component of campaigns to improve a community''s health.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Health equity: Economic inequality', 'Poor health outcomes appear to be an effect of economic inequality across a population. Nations and regions with greater economic inequality show poorer outcomes in life expectancy, mental health, drug abuse, obesity, educational performance, teenage birthrates, and ill health due to violence. On an international level, there is a positive correlation between developed countries with high economic equality and longevity. Based on where a person lives and how much money they make, experts can predict roughly how long that person will live. According to the World Health Organization (WHO) in 2017, a baby born and raised in Africa will die an average of sixteen years sooner than a child born at the same time in Europe. This is unrelated to average income per capita in wealthy nations. Economic gain only impacts life expectancy to a great degree in countries in which the mean per capita annual income is less than approximately $25,000. The United States shows exceptionally low health outcomes for a developed country, despite having the highest national healthcare expenditure in the world. The US ranks 31st in life expectancy. Americans have a lower life expectancy than their European counterparts, even when factors such as race, income, diet, smoking, and education are controlled for.', 'Wikipedia: Health equity', 'https://en.wikipedia.org/w/index.php?title=Health_equity&oldid=1378982805', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Poor health outcomes appear to be an effect of economic inequality across a population. Nations and regions with greater economic inequality show poorer outcomes in life expectancy, mental health, drug abuse, obesity, educational performance, teenage birthrates, and ill health due to violence. On an international level, there is a positive correlation between developed countries with high economic equality and longevity. Based on where a person lives and how much money they make, experts can predict roughly how long that person will live. According to the World Health Organization (WHO) in 2017, a baby born and raised in Africa will die an average of sixteen years sooner than a child born at the same time in Europe. This is unrelated to average income per capita in wealthy nations. Economic gain only impacts life expectancy to a great degree in countries in which the mean per capita annual income is less than approximately $25,000. The United States shows exceptionally low health outcomes for a developed country, despite having the highest national healthcare expenditure in the world. The US ranks 31st in life expectancy. Americans have a lower life expectancy than their European counterparts, even when factors such as race, income, diet, smoking, and education are controlled for.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'inequality-demographics', 'Health equity: Economic inequality', 'Relative inequality negatively affects health on an international, national, and institutional levels. The patterns seen internationally hold true between more and less economically equal states in the United States, that is, more equal states show more desirable health outcomes. Importantly, inequality can have a negative health impact on members of lower echelons of institutions. The Whitehall I and II studies looked at the rates of cardiovascular disease and other health risks in British civil servants and found that, even when lifestyle factors were controlled for, members of lower status in the institution showed increased mortality and morbidity on a sliding downward scale from their higher status counterparts. The negative aspects of inequality are spread across the population. For example, when comparing the United States (a more unequal nation) to England (a less unequal nation), the US shows higher rates of diabetes, hypertension, cancer, lung disease, and heart disease across all income levels. This is also true of the difference between mortality across all occupational classes in highly equal Sweden as compared to less-equal England. Unconditional cash transfers for reducing poverty used by some programs in the developing world appear to lead to a reduction in the likelihood of being sick. Such evidence can guide resource allocations to effective interventions.', 'Wikipedia: Health equity', 'https://en.wikipedia.org/w/index.php?title=Health_equity&oldid=1378982805', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'inequality-demographics' and body = 'Relative inequality negatively affects health on an international, national, and institutional levels. The patterns seen internationally hold true between more and less economically equal states in the United States, that is, more equal states show more desirable health outcomes. Importantly, inequality can have a negative health impact on members of lower echelons of institutions. The Whitehall I and II studies looked at the rates of cardiovascular disease and other health risks in British civil servants and found that, even when lifestyle factors were controlled for, members of lower status in the institution showed increased mortality and morbidity on a sliding downward scale from their higher status counterparts. The negative aspects of inequality are spread across the population. For example, when comparing the United States (a more unequal nation) to England (a less unequal nation), the US shows higher rates of diabetes, hypertension, cancer, lung disease, and heart disease across all income levels. This is also true of the difference between mortality across all occupational classes in highly equal Sweden as compared to less-equal England. Unconditional cash transfers for reducing poverty used by some programs in the developing world appear to lead to a reduction in the likelihood of being sick. Such evidence can guide resource allocations to effective interventions.');
commit;
